#include <windows.h>
#include <wincrypt.h>

/* A key pair signs as strong naming does: the PRIVATEKEYBLOB of a 512-bit RSA key goes into a provider, which keeps it once
   the handle of the import is destroyed and signs a SHA-1 hash with it. The signature must match the one OpenSSL made of the same message with the same key, byte for byte (PKCS #1 v1.5 is
   deterministic), the public half must come out as a PUBLICKEYBLOB and check that signature, and a changed message must not pass. */

