static const BYTE message[] = "Raven signs this";

static int same(const BYTE *left, const BYTE *right, DWORD length)
{
	for (DWORD at = 0; at < length; ++at)
		if (left[at] != right[at])
			return 0;
	return 1;
}

int raven_entry(void)
{
	HCRYPTPROV provider;
	HCRYPTKEY key, user, public_key;
	HCRYPTHASH hash;
	BYTE signature[64], exported[128];
	DWORD length = 0;
	if (!CryptAcquireContextW(&provider, NULL, NULL, PROV_RSA_FULL, CRYPT_VERIFYCONTEXT)) return 1;
	if (!CryptImportKey(provider, pair, sizeof pair, 0, CRYPT_EXPORTABLE, &key)) return 2;
	// The pair stays with the provider once the handle of the import is gone.
	CryptDestroyKey(key);
	if (!CryptGetUserKey(provider, AT_SIGNATURE, &user)) return 3;
	DWORD algorithm = 0, size = sizeof algorithm;
	if (!CryptGetKeyParam(user, KP_ALGID, (BYTE *)&algorithm, &size, 0) || algorithm != CALG_RSA_SIGN) return 14;
	if (!CryptCreateHash(provider, CALG_SHA1, 0, 0, &hash)) return 4;
	if (!CryptHashData(hash, message, sizeof message - 1, 0)) return 5;
	if (!CryptSignHashW(hash, AT_SIGNATURE, NULL, 0, NULL, &length) || length != sizeof signature) return 6;
	if (!CryptSignHashW(hash, AT_SIGNATURE, NULL, 0, signature, &length)) return 7;
	if (!same(signature, expected, sizeof expected)) return 8;
	length = sizeof exported;
	if (!CryptExportKey(user, 0, PUBLICKEYBLOB, 0, exported, &length) || length != 20 + 64) return 9;
	if (exported[0] != PUBLICKEYBLOB || exported[8] != 'R' || exported[11] != '1' || !same(exported + 20, pair + 20, 64)) return 10;
	if (!CryptImportKey(provider, exported, length, 0, 0, &public_key)) return 11;
	if (!CryptVerifySignatureW(hash, signature, sizeof signature, public_key, NULL, 0)) return 12;
	CryptDestroyHash(hash);
	CryptCreateHash(provider, CALG_SHA1, 0, 0, &hash);
	CryptHashData(hash, message, sizeof message - 2, 0);
	if (CryptVerifySignatureW(hash, signature, sizeof signature, public_key, NULL, 0) || GetLastError() != (DWORD)NTE_BAD_SIGNATURE) return 13;
	CryptDestroyHash(hash);
	CryptDestroyKey(public_key);
	CryptDestroyKey(user);
	CryptReleaseContext(provider, 0);
	return 0;
}
